parameters.jsCode:
// ตรวจใบแจ้งหนี้ด้วยกฎที่แน่นอน ไม่ใช้โมเดล ทุกข้อที่ไม่ผ่านถูกเก็บเป็นเหตุผล
const x = $('ดึงข้อมูลใบแจ้งหนี้').item.json.output;
const text = $('เก็บชื่อไฟล์').item.json.text;
const db = $json;
const r2 = n => Math.round(Number(n) * 100) / 100;
const fmt = n => Number(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const problems = [];

// 1. เลขผู้เสียภาษี 13 หลักและหลักตรวจสอบ
const id = String(x.vendor_tax_id || '').replace(/\D/g, '');
const checkDigit = id.length === 13
  ? (11 - [...id.slice(0, 12)].reduce((s, d, i) => s + Number(d) * (13 - i), 0) % 11) % 10 : -1;
if (id.length !== 13 || checkDigit !== Number(id[12])) problems.push(`เลขผู้เสียภาษี ${x.vendor_tax_id} ไม่ถูกต้อง`);
// 2. ผู้ขายต้องอยู่ในทะเบียน และเลขที่ใบแจ้งหนี้ต้องไม่ซ้ำ
if (!db.vendor_name) problems.push(`ผู้ขายเลขผู้เสียภาษี ${id} ไม่อยู่ในทะเบียนผู้ขาย`);
if (db.duplicate) problems.push(`เลขที่ ${x.invoice_no} ของผู้ขายรายนี้เคยรับแล้ว (สถานะ ${db.duplicate_status})`);
// 3. ตัวเลขต้องสอดคล้องกัน
const lines = x.lines ?? [];
for (const l of lines) {
  if (Math.abs(r2(l.qty * l.unit_price) - r2(l.amount)) > 0.01) problems.push(`รายการ ${l.description}: ${l.qty} x ${fmt(l.unit_price)} ไม่เท่ากับ ${fmt(l.amount)}`);
}
const sum = r2(lines.reduce((s, l) => s + Number(l.amount), 0));
if (Math.abs(sum - r2(x.subtotal)) > 0.01) problems.push(`ผลรวมรายการ ${fmt(sum)} ไม่เท่ากับยอดรวม ${fmt(x.subtotal)}`);
if (Math.abs(r2(x.subtotal * 0.07) - r2(x.vat)) > 0.01) problems.push(`VAT ${fmt(x.vat)} ไม่เท่ากับ 7% ของ ${fmt(x.subtotal)} ซึ่งเท่ากับ ${fmt(r2(x.subtotal * 0.07))}`);
if (Math.abs(r2(Number(x.subtotal) + Number(x.vat)) - r2(x.total)) > 0.01) problems.push(`ยอดรวมทั้งสิ้น ${fmt(x.total)} ไม่เท่ากับยอดรวมบวก VAT`);
// 4. ตัวเลขที่โมเดลดึงมาต้องมีอยู่จริงในเอกสาร กันโมเดลแต่งหรือแก้ตัวเลขเอง
for (const [name, v] of [['ยอดรวม', x.subtotal], ['VAT', x.vat], ['ยอดรวมทั้งสิ้น', x.total]]) {
  if (!text.includes(fmt(v))) problems.push(`ไม่พบ${name} ${fmt(v)} ในข้อความของเอกสาร`);
}
if (!text.includes(String(x.invoice_no))) problems.push(`ไม่พบเลขที่ ${x.invoice_no} ในข้อความของเอกสาร`);
if (id && !text.replace(/\s/g, '').includes(id)) problems.push(`ไม่พบเลขผู้เสียภาษี ${id} ในข้อความของเอกสาร`);

return { json: { ...x, vendor_tax_id: id, registered_name: db.vendor_name, lines_sum: sum, problems, pass: problems.length === 0,
                 file_name: $('เก็บชื่อไฟล์').item.json.file_name } };

